      { name: "tsdoc", specifier: "eslint-plugin-tsdoc" },
      { name: "tsdoc-require-2", specifier: "eslint-plugin-tsdoc-require-2" },
    ],
    rules: { "vite-plus/prefer-vite-plus-imports": "error" },
    options: { typeAware: true, typeCheck: true },
    overrides: [
      {
